OriginActivationLimitAsyncWaiter::OriginActivationLimitAsyncWaiter(
    OriginActivationLimit* proxy) : proxy_(proxy) {}

OriginActivationLimitAsyncWaiter::~OriginActivationLimitAsyncWaiter() = default;


void OriginActivationLimitAsyncWaiter::CanExtend(
    const std::string& order_id, const std::string& receipt_payload, ExtendEligibilityPtr* out_eligibility) {
  base::RunLoop loop;
  proxy_->CanExtend(
      std::move(order_id),
      std::move(receipt_payload),
      base::BindOnce(
          [](base::RunLoop* loop,
             ExtendEligibilityPtr* out_eligibility
,
             ExtendEligibilityPtr eligibility) {*out_eligibility = std::move(eligibility);
            loop->Quit();
          },
          &loop,
          out_eligibility));
  loop.Run();
}

ExtendEligibilityPtr OriginActivationLimitAsyncWaiter::CanExtend(
    const std::string& order_id, const std::string& receipt_payload) {
  ExtendEligibilityPtr async_wait_result;
  CanExtend(std::move(order_id),std::move(receipt_payload),&async_wait_result);
  return async_wait_result;
}

void OriginActivationLimitAsyncWaiter::Extend(
    const std::string& order_id, const std::string& receipt_payload, bool* out_succeeded, std::string* out_error_code) {
  base::RunLoop loop;
  proxy_->Extend(
      std::move(order_id),
      std::move(receipt_payload),
      base::BindOnce(
          [](base::RunLoop* loop,
             bool* out_succeeded
,
             std::string* out_error_code
,
             bool succeeded,
             const std::string& error_code) {*out_succeeded = std::move(succeeded);*out_error_code = std::move(error_code);
            loop->Quit();
          },
          &loop,
          out_succeeded,
          out_error_code));
  loop.Run();
}








